import{_ as r,a0 as a,w as i,s as d,ao as l,I as p,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何設置Ubuntu14.04 的 SSH 無密碼登錄 | LCTT x X-CMD","titleTemplate":false,"description":"如何設置Ubuntu14.04 的 SSH 無密碼登錄 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何設置Ubuntu14.04 的 SSH 無密碼登錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何設置Ubuntu14.04 的 SSH 無密碼登錄 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150302 How to Setup Passwordless SSH Logon to Ubuntu 14.04","title":"如何設置Ubuntu14.04 的 SSH 無密碼登錄","tag":"201504","desc":""},"relativePath":"201504/20150302 How to Setup Passwordless SSH Logon to Ubuntu 14.04.md","filePath":"[post].md"}'),u={name:"201504/20150302 How to Setup Passwordless SSH Logon to Ubuntu 14.04.md"};function S(h,e,g,m,b,H){const s=a("Link");return i(),d("div",null,[e[13]||(e[13]=l(`<h1 id="如何設置ubuntu14-04-的-ssh-無密碼登錄" tabindex="-1">如何設置Ubuntu14.04 的 SSH 無密碼登錄 <a class="header-anchor" href="#如何設置ubuntu14-04-的-ssh-無密碼登錄" aria-label="Permalink to “如何設置Ubuntu14.04 的 SSH 無密碼登錄”">​</a></h1><p>大家好，今天我來向大家介紹如何在 Ubuntu12.04 上設置 SSH 的無密碼登錄功能。僅在工作站上有正確的（公私）密鑰對以供匹配時SSH服務端才會允許你登錄，反之訪問將不會被允許。</p><p>正常情況下，我們需要連上SSH的控制台輸入用户名及其密碼才行。如果兩者全部正確，我們就可以訪問，反之訪問被服務端拒絕。不過相比而言還有一種比用密碼更安全的登錄方式，我們可以在登錄SSH時通過加密密鑰進行無密碼登錄。</p><p>如果你想啓用這個安全的方式，我們只需簡單的禁用密碼登錄並只允許加密密鑰登錄即可。使用這種方式時，客户端計算機上會產生一對私鑰和公鑰。接着客户端得把公鑰上傳到SSH服務端的authorized_key文件中去。在授予訪問前，服務器及客户端電腦會校驗這個密鑰對。如果服務器上的公鑰與客服端提交的私鑰匹配則授予訪問權限，否則訪問被拒絕。</p><p>這是認證到SSH服務器的非常安全的一種做法，如果你想為單一的SSH用户登錄實現安全登錄，這也是備受推崇的方式。這裏快速的過一遍如何啓用無密碼登錄SSH的配置過程。</p><h3 id="_1-安裝openssh服務端" tabindex="-1">1.安裝Openssh服務端 <a class="header-anchor" href="#_1-安裝openssh服務端" aria-label="Permalink to “1.安裝Openssh服務端”">​</a></h3><p>首先，我們需要更新我們的本地庫索引。所以如下所見，我們需要先輸入“apt-get update”</p><pre><code>$ sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/updating-repo-list.png" alt="Updating Repo Index"></p><p>現在我們可以通過以下命令安裝openssh-server：</p><pre><code>$ sudo apt-get install openssh-server
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/installing-openssh-server.png" alt="Installing openssh server"></p><h3 id="_2-開啓openssh服務" tabindex="-1">2. 開啓openssh服務 <a class="header-anchor" href="#_2-開啓openssh服務" aria-label="Permalink to “2. 開啓openssh服務”">​</a></h3><p>在OpenSSH已經成功安裝在Ubuntu14.04操作系統上了之後，我們要啓動OpenSSH的服務。以下命令讓你啓動/開啓服務。</p><pre><code>$ sudo service ssh start
</code></pre><p>或</p><pre><code>$ sudo /etc/init.d/ssh start
</code></pre><h3 id="_3-配置密鑰對" tabindex="-1">3. 配置密鑰對 <a class="header-anchor" href="#_3-配置密鑰對" aria-label="Permalink to “3. 配置密鑰對”">​</a></h3><p>在我們安裝並啓動了OpenSSH服務以後。現在終於到了要我們搞定公私鑰對的時候了，在終端中運行以下命令：</p><pre><code>$ ssh-keygen -t rsa
</code></pre><p>在運行完以上命令了以後，我們需要回答一系列的問題。首先選擇保存密鑰的路徑，按回車將會選擇默認路徑即家目錄的一個隱藏的.ssh文件夾。下一個提示是請輸入口令提醒。我個人將此留空（直接回車）。之後密鑰對就會創建，大功告成。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/generating-key-pair.png" alt="Generating Key Pair"></p><p>在密鑰對生成以後，我們需要將<strong>客户端上的公鑰複製到SSH服務端</strong>或者主機，來創建對客户端的信任關係。運行以下命令複製客户端的公鑰到服務端。</p><pre><code>$ ssh-copy-id user@ip_address
</code></pre><p>在公鑰上傳之後，我們現在可以禁用通過密碼登陸SSH的方式了。為此，我們需要通過以下命令用文本編輯器打開<strong>/etc/ssh/ssh_config</strong>。</p><pre><code>$ sudo nano /etc/ssh/sshd_config
</code></pre><p>現在，我們需要按照下圖所示去掉幾行註釋並進行一些賦值。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/configuring-sshd_config.png" alt="Configuring sshd Config"></p><h3 id="_4-重啓ssh服務" tabindex="-1">4. 重啓SSH服務 <a class="header-anchor" href="#_4-重啓ssh服務" aria-label="Permalink to “4. 重啓SSH服務”">​</a></h3><p>最後，在我們配置完SSH服務端後，為了使改動生效我們需要重啓SSH服務。在終端或控制台運行以下命令重啓。</p><pre><code>$ sudo service ssh restart
</code></pre><p>或</p><pre><code>$ sudo /etc/init.d/ssh restart
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/restarting-ssh.png" alt="Restarting ssh"></p><p>現在，我們可以試試不用密碼僅用密鑰對的方式登錄ssh服務端了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>太好了！我們成功的配置了無密碼登錄SSH。使用加密密鑰對進行SSH服務器認證是非常安全的一種做法，如果你想為SSH的單一用户登錄實施安全的認證這也是備受推崇的方式。所以，如果你還有什麼問題或建議，請在意見框中向我們反饋。很欣慰你能讀完，希望你能喜歡加密的SSH安全登錄 😃</p><hr>`,38)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),o(s,{href:"http://linoxide.com/ubuntu-how-to/setup-passwordless-ssh-logon-ubuntu-14-04/"},{default:n(()=>[...e[0]||(e[0]=[t("http://linoxide.com/ubuntu-how-to/setup-passwordless-ssh-logon-ubuntu-14-04/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=t("作者：",-1)),o(s,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[2]||(e[2]=[t("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),o(s,{href:"https://github.com/martin2011qi"},{default:n(()=>[...e[3]||(e[3]=[t("martin2011qi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),o(s,{href:"http://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const _=r(u,[["render",S]]);export{x as __pageData,_ as default};
